// Linked List Cycle detection simulation (Floyd's Tortoise and Hare)
let list = AnimatedLinkedList<Int>()
for v in 1...4 {
    list.append(v)
}

func hasCycle(_ l: AnimatedLinkedList<Int>) -> Bool {
    var slow = 0
    var fast = 0
    while fast < l.count && fast + 1 < l.count {
        slow += 1
        fast += 2
        if slow == fast {
            return true
        }
    }
    return false
}

let cycleFound = hasCycle(list)
